<article class="product-card"><span class="badge-soft"><?= $p['is_featured']?'Lựa chọn nổi bật':'Chính hãng' ?></span><a href="/products/<?= $p['id'] ?>"><img class="product-image" src="<?= e($p['image']??'/assets/img/device-'.$p['category_id'].'.svg') ?>" alt="<?= e($p['name']) ?>" loading="lazy"><div class="product-brand"><?= e($p['brand_name']) ?></div><h3><?= e($p['name']) ?></h3></a><div class="stock"><?= $p['stock']>0?'● Còn hàng':'Hết hàng' ?></div><div class="price"><?= money($p['price']) ?></div><div class="product-actions"><form action="/cart/update" method="post" data-ajax><?= App\Core\Csrf::field() ?><input type="hidden" name="product_id" value="<?= $p['id'] ?>"><button type="submit" id="add-cart-<?= $p['id'] ?>" class="btn btn-primary" <?= $p['stock']<1?'disabled':'' ?>>+ Thêm giỏ hàng</button></form><form action="/compare/update" method="post" data-ajax><?= App\Core\Csrf::field() ?><input type="hidden" name="product_id" value="<?= $p['id'] ?>"><button type="submit" id="compare-<?= $p['id'] ?>" class="btn btn-light" aria-label="So sánh <?= e($p['name']) ?>">⇄</button></form></div></article>
